#include <libcamera/stream.h>

#include "core/libcamera_app.hpp"

#include "post_processing_stages/post_processing_stage.hpp"

using Stream = libcamera::Stream;

#include "opencv2/core.hpp"
#include "opencv2/imgproc.hpp"

using namespace cv;

class GrayStage : public PostProcessingStage
{
public:
	GrayStage(LibcameraApp *app) : PostProcessingStage(app) {}

	char const *Name() const override;

	void Read(boost::property_tree::ptree const &params) override {}
	
	void Configure() override;

	void AdjustConfig(std::string const &use_case, StreamConfiguration *config) override;

	bool Process(CompletedRequestPtr &completed_request) override;

private:
	Stream *stream_;
};

#define NAME "gray_cv"

char const *GrayStage::Name() const
{
	return NAME;
}

void GrayStage::Configure()
{
	stream_ = app_->GetMainStream();
}

void GrayStage::AdjustConfig(std::string const &use_case, StreamConfiguration *config)
{
	config->pixelFormat = libcamera::PixelFormat(libcamera::formats::R10_CSI2P);// R8 R10 R12 R10_CSI2P
}

bool GrayStage::Process(CompletedRequestPtr &completed_request)
{
	
	StreamInfo info = app_->GetStreamInfo(stream_);
	libcamera::Span<uint8_t> buffer = app_->Mmap(completed_request->buffers[stream_])[0];
	uint8_t *ptr = (uint8_t *)buffer.data();

	uint8_t value = 128;
	int num = (info.stride * info.height) / 2;
	Mat src = Mat(info.height, info.width, CV_8U, ptr, info.stride);
	
	memset(ptr + info.stride * info.height, value, num);

	cvtColor(src, src, COLOR_BGR2GRAY);

	return false;
}

static PostProcessingStage *Create(LibcameraApp *app)
{
	return new GrayStage(app);
}

static RegisterStage reg(NAME, &Create);
```

